/**
 * TASK: Complete EncryptedChannel, the third layer of a message pipeline.
 * MessageChannel and CompressingChannel are provided -- do not edit them.
 *
 * Every channel transforms a message on its way into the log. Each layer does
 * its own small job and then delegates the rest to the layer beneath it with
 * super.transform(...), so the transformations COMPOSE in a fixed order:
 *
 *   MessageChannel      leaves the text alone
 *   CompressingChannel  removes every space
 *   EncryptedChannel    shifts each letter along the alphabet by "shift"
 *
 * So with a shift of 1, send("hello world") must log "ifmmpxpsme":
 * the spaces go first, then the letters shift.
 *
 * The shift is a simple Caesar cipher: letters wrap around inside their own
 * case ('z' with a shift of 1 becomes 'a', 'Z' becomes 'A') and anything that
 * is not a letter is left exactly as it is.
 *
 * name() must return "encrypted(" + the inherited name + ")".
 */
abstract class MessageChannel {
    private final java.util.List<String> sent = new java.util.ArrayList<>();

    public void send(String message) {
        sent.add(transform(message));
    }

    protected String transform(String message) {
        return message;
    }

    public java.util.List<String> log() {
        return sent;
    }

    public abstract String name();
}

class CompressingChannel extends MessageChannel {
    @Override
    protected String transform(String message) {
        return super.transform(message).replace(" ", "");
    }

    @Override
    public String name() {
        return "compressing";
    }
}

public class EncryptedChannel extends CompressingChannel {

    private final int shift;

    public EncryptedChannel(int shift) {
        this.shift = shift;
    }

    public int getShift() {
        return shift;
    }

    @Override
    protected String transform(String message) {
        // TODO: let the layer below run first, then shift the letters
        return "";
    }

    @Override
    public String name() {
        // TODO: wrap the inherited name
        return "";
    }
}

