public class EncryptedChannelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static Object firstLogged(int shift, String message) {
        try {
            EncryptedChannel channel = new EncryptedChannel(shift);
            channel.send(message);
            return channel.log().get(0);
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        check("spaces are removed before the shift", "ifmmpxpsme", firstLogged(1, "hello world"));
        check("lower case wraps around", "abc", firstLogged(3, "xyz"));
        check("upper case wraps inside its own case", "Afub", firstLogged(1, "Zeta"));
        check("digits and punctuation pass through", "bc1!", firstLogged(1, "ab 1!"));
        check("a shift of zero still compresses", "keepcalm", firstLogged(0, "keep calm"));
        check("name wraps the inherited name", "encrypted(compressing)",
                safe(() -> new EncryptedChannel(5).name()));
        check("the log keeps one entry per send", "2|ifmmp|xpsme",
                safe(() -> {
                    EncryptedChannel channel = new EncryptedChannel(1);
                    channel.send("hello");
                    channel.send("world");
                    return channel.log().size() + "|" + channel.log().get(0) + "|" + channel.log().get(1);
                }));

        MessageChannel plain = new CompressingChannel();
        plain.send("hello world");
        check("the provided layer is unchanged", "helloworld", safe(() -> plain.log().get(0)));

        MessageChannel polymorphic = new EncryptedChannel(1);
        polymorphic.send("go now");
        check("send through the base type still runs every layer", "hpopx",
                safe(() -> polymorphic.log().get(0)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

